async function run() {
  const pages = figma.root.children;
  let ws = pages.find(p => p.name === '03 · Workspace');
  await figma.setCurrentPageAsync(ws);

  // Load Inter fonts
  const loadFonts = async () => {
    const styles = [["Inter","Regular"],["Inter","Medium"],["Inter","Semi Bold"],["Inter","Bold"],["Inter","Extra Bold"]];
    for (const [f,s] of styles) { try { await figma.loadFontAsync({family:f, style:s}); } catch(e){} }
  };
  await loadFonts();

  const WHITE = {type:'SOLID', color:{r:1,g:1,b:1}};
  const BLACK = {type:'SOLID', color:{r:0,g:0,b:0}};
  const GRAY = {type:'SOLID', color:{r:0.42,g:0.44,b:0.45}};
  const CYAN = {type:'SOLID', color:{r:0.906,g:0.976,b:0.992}};

  function text(str, size, weight, color, opts={}) {
    const t = figma.createText();
    t.characters = str;
    t.fontSize = size;
    t.fontName = {family:"Inter", style:weight};
    t.fills = [color];
    if (opts.lh) t.lineHeight = {value: opts.lh, unit:"PIXELS"};
    return t;
  }

  // ---- HEADER component ----
  function instantiate(key) {
    const comp = figma.getNodeById(key);
    if (!comp || comp.type !== 'COMPONENT') { console.log('missing '+key); return null; }
    return comp.createInstance();
  }

  const header = figma.createComponent();
  header.name = 'Header';
  header.resize(1440, 128);
  header.fills = [WHITE];
  const hLayout = figma.createFrame();
  hLayout.name = 'HeaderLayout';
  hLayout.layoutMode = 'HORIZONTAL';
  hLayout.primaryAxisAlignItems='CENTER';
  hLayout.counterAxisAlignItems='CENTER';
  hLayout.paddingLeft=100; hLayout.paddingRight=100;
  hLayout.itemSpacing=0;
  hLayout.resize(1440,128);
  header.appendChild(hLayout);

  const logo = instantiate('7:15');
  if (logo) hLayout.appendChild(logo);

  const spacer = figma.createFrame(); spacer.resize(1,1); spacer.fills=[];
  hLayout.appendChild(spacer);

  // nav items
  const navItems = ['Home','Recipes','Blog','Contact','About us'];
  const navFrame = figma.createFrame();
  navFrame.name='Nav';
  navFrame.layoutMode='HORIZONTAL';
  navFrame.itemSpacing=40;
  navFrame.counterAxisAlignItems='CENTER';
  navFrame.fills=[];
  hLayout.appendChild(navFrame);
  const navTexts = [];
  for (const label of navItems) {
    const t = text(label, 16, 'Regular', GRAY);
    navFrame.appendChild(t);
    navTexts.push(t);
  }

  const spacer2 = figma.createFrame(); spacer2.fills=[];
  hLayout.appendChild(spacer2);

  const social = figma.createFrame(); social.name='Social';
  social.layoutMode='HORIZONTAL'; social.itemSpacing=24; social.fills=[]; social.counterAxisAlignItems='CENTER';
  hLayout.appendChild(social);
  for (const k of ['7:48','7:50','7:49']) {
    const inst = instantiate(k);
    if (inst) social.appendChild(inst);
  }

  // flex spacers to distribute
  hLayout.layoutMode='HORIZONTAL';
  hLayout.primaryAxisAlignItems='SPACE_BETWEEN';
  spacer.layoutGrow=1; spacer2.layoutGrow=1;

  header.name='Header';
  console.log('Header built');

  return 'done';
}
